-- CAT-009: explicit, single-level, owner-consented billing relationships.
CREATE TABLE nc_customer_hierarchies(customer_id TEXT PRIMARY KEY REFERENCES nc_customers(id),parent_id TEXT NOT NULL REFERENCES nc_customers(id),billing_mode TEXT NOT NULL CHECK(billing_mode IN ('consolidated','separate')),revision INTEGER NOT NULL,authorized_by TEXT NOT NULL,authorized_at INTEGER NOT NULL,CHECK(customer_id<>parent_id));
CREATE TABLE nc_hierarchy_sources(invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),source_invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),source_fingerprint TEXT NOT NULL,PRIMARY KEY(invoice_id,source_invoice_id));
CREATE TABLE nc_hierarchy_consumed(source_invoice_id TEXT PRIMARY KEY REFERENCES nc_invoices(id),invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),period_start TEXT NOT NULL,billing_key TEXT NOT NULL,UNIQUE(subscription_id,period_start,billing_key));
CREATE TABLE nc_invoice_payers(invoice_id TEXT PRIMARY KEY REFERENCES nc_invoices(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),payer_id TEXT NOT NULL REFERENCES nc_customers(id),hierarchy_revision INTEGER NOT NULL,authorized_by TEXT NOT NULL,authorized_at INTEGER NOT NULL);
CREATE TABLE nc_hierarchy_commitments(id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES nc_customers(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),from_date TEXT NOT NULL,to_date TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,CHECK(to_date>from_date));
CREATE TRIGGER nc_customer_hierarchies_generation_insert AFTER insert ON nc_customer_hierarchies BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_customer_hierarchies_generation_update AFTER update ON nc_customer_hierarchies BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_customer_hierarchies_generation_delete AFTER delete ON nc_customer_hierarchies BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_sources_generation_insert AFTER insert ON nc_hierarchy_sources BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_sources_generation_update AFTER update ON nc_hierarchy_sources BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_sources_generation_delete AFTER delete ON nc_hierarchy_sources BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_consumed_generation_insert AFTER insert ON nc_hierarchy_consumed BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_consumed_generation_update AFTER update ON nc_hierarchy_consumed BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_consumed_generation_delete AFTER delete ON nc_hierarchy_consumed BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_invoice_payers_generation_insert AFTER insert ON nc_invoice_payers BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_invoice_payers_generation_update AFTER update ON nc_invoice_payers BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_invoice_payers_generation_delete AFTER delete ON nc_invoice_payers BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_commitments_generation_insert AFTER insert ON nc_hierarchy_commitments BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_commitments_generation_update AFTER update ON nc_hierarchy_commitments BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_commitments_generation_delete AFTER delete ON nc_hierarchy_commitments BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_hierarchy_sources_update BEFORE UPDATE ON nc_hierarchy_sources WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_hierarchy_sources_delete BEFORE DELETE ON nc_hierarchy_sources WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
